package com.accountcopilot;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("genie")
public interface AccountCopilotConfig extends Config
{
	// ---- the one field a normal user sets ----

	@ConfigItem(keyName = "linkKey", name = "Link key", position = 1,
		description = "Paste the key from the Genie app (or rsgenie.com) so your characters "
			+ "sync to your account. Get it in the app under Settings, or from onboarding.")
	default String linkKey() { return ""; }

	// ---- privacy toggles ----

	@ConfigItem(keyName = "syncFriends", name = "Find friends on Genie", position = 2,
		description = "Discover which of your in-game friends use Genie. Sends anonymized hashes "
			+ "of your friends list, never the names. Matches only reveal players who already "
			+ "linked their own account to Genie.")
	default boolean syncFriends() { return true; }

	@ConfigItem(keyName = "nameOnBoards", name = "Show my name on achievement boards", position = 3,
		description = "When you complete a community achievement, list your username on its public "
			+ "board so friends can see it. Off = you are counted anonymously.")
	default boolean nameOnBoards() { return false; }

	@ConfigItem(keyName = "shareTelemetry", name = "Share anonymous rate data", position = 4,
		description = "Sends anonymized samples (hashed account id, xp gained, gear worn, npc "
			+ "fought) to improve rate estimates for everyone. No names, chat, or location. "
			+ "Turning this off does not affect your own plans.")
	default boolean shareTelemetry() { return true; }

	// ---- advanced / self-hosting only (hidden from normal users) ----

	@ConfigItem(keyName = "apiUrl", name = "Backend URL", hidden = true,
		description = "Genie backend. Only change this if you are self-hosting.")
	default String apiUrl() { return "https://www.rsgenie.com"; }

	@ConfigItem(keyName = "apiToken", name = "API token", hidden = true, secret = true,
		description = "Optional backend token. The free tier works without one.")
	default String apiToken() { return ""; }
}

package com.accountcopilot;

/*
 * Thin client for the Account Copilot backend.
 * ARCHITECTURE NOTE (see repo docs): this plugin is a dumb screen.
 * All intelligence (method DB, live prices, solver, DPS scaling) is server-side.
 * The plugin POSTs an account-state snapshot and renders the returned plan. Nothing else.
 *
 * Plugin Hub compliance: a data-submission warning must be shown on first run,
 * describing exactly what is sent (stats, quest states, equipment, xp gains).
 */
import com.google.gson.Gson;
import java.io.IOException;
import okhttp3.*;

public class CopilotApiClient
{
	private static final String BASE = "https://api.accountcopilot.example/v1"; // TODO real host
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private final OkHttpClient http;
	private final Gson gson;

	public CopilotApiClient(OkHttpClient http, Gson gson) { this.http = http; this.gson = gson; }

	public void fetchPlan(AccountSnapshot snapshot, String token, Callback cb)
	{
		Request req = new Request.Builder()
			.url(BASE + "/plan")
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(snapshot)))
			.build();
		http.newCall(req).enqueue(cb);
	}
}

