/**
 * The plugin is a thin sync bridge now: all the planning lives in the Genie app
 * and on rsgenie.com. This panel just shows sync status and opens the app.
 */
public class CopilotPanel extends PluginPanel
{
	private static final Color ORANGE = new Color(255, 140, 46);
	private static final Color GREEN = new Color(52, 210, 123);
	private static final Color MUTED = new Color(139, 147, 167);

	private final AccountCopilotPlugin plugin;
	private final JLabel status = new JLabel();
	private final JLabel hint = new JLabel();

	CopilotPanel(AccountCopilotPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(14, 12, 12, 12));

		JPanel col = new JPanel();
		col.setLayout(new BoxLayout(col, BoxLayout.Y_AXIS));
		col.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Genie");
		title.setForeground(Color.WHITE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 18f));
		title.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel tag = new JLabel("Your next move, every time you log in.");
		tag.setForeground(MUTED);
		tag.setFont(tag.getFont().deriveFont(12f));
		tag.setAlignmentX(Component.LEFT_ALIGNMENT);

		status.setAlignmentX(Component.LEFT_ALIGNMENT);
		status.setFont(status.getFont().deriveFont(Font.BOLD, 13f));

		hint.setAlignmentX(Component.LEFT_ALIGNMENT);
		hint.setForeground(MUTED);
		hint.setFont(hint.getFont().deriveFont(11.5f));

		JButton open = new JButton("Open Genie");
		open.setAlignmentX(Component.LEFT_ALIGNMENT);
		open.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		open.setBackground(ORANGE);
		open.setForeground(new Color(30, 20, 8));
		open.setFont(open.getFont().deriveFont(Font.BOLD, 13f));
		open.setFocusPainted(false);
		open.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		open.addActionListener(e -> plugin.openDashboard());

		col.add(title);
		col.add(Box.createVerticalStrut(3));
		col.add(tag);
		col.add(Box.createVerticalStrut(16));
		col.add(status);
		col.add(Box.createVerticalStrut(4));
		col.add(hint);
		col.add(Box.createVerticalStrut(16));
		col.add(open);
		col.add(Box.createVerticalStrut(14));
		col.add(step("1", "Paste your Link key in the plugin settings (gear icon)."));
		col.add(Box.createVerticalStrut(6));
		col.add(step("2", "Log into the game. Your account syncs automatically."));
		col.add(Box.createVerticalStrut(6));
		col.add(step("3", "Open Genie to see plans picked for your account."));

		add(col, BorderLayout.NORTH);
		setSynced(false, null);
	}

	/** Called by the plugin when a snapshot posts or the link key is missing. */
	public void setSynced(boolean synced, String player)
	{
		if (plugin != null && plugin.linkKeyMissing())
		{
			status.setForeground(ORANGE);
			status.setText("No link key yet");
			hint.setText("Add your key in settings, then log in.");
		}
		else if (synced && player != null)
		{
			status.setForeground(GREEN);
			status.setText("Synced as " + player);
			hint.setText("Genie is tracking this account.");
		}
		else
		{
			status.setForeground(MUTED);
			status.setText("Waiting for login");
			hint.setText("Log into the game to sync.");
		}
		revalidate();
		repaint();
	}

	private JPanel step(String n, String txt)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
		JLabel num = new JLabel(n, SwingConstants.CENTER);
		num.setPreferredSize(new Dimension(22, 22));
		num.setOpaque(true);
		num.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		num.setForeground(ORANGE);
		num.setFont(num.getFont().deriveFont(Font.BOLD, 11f));
		JLabel t = new JLabel("<html>" + txt + "</html>");
		t.setForeground(new Color(200, 205, 215));
		t.setFont(t.getFont().deriveFont(11.5f));
		row.add(num, BorderLayout.WEST);
		row.add(t, BorderLayout.CENTER);
		return row;
	}
}

package com.accountcopilot;

/*
 * Community achievements tracker (v1). See ACHIEVEMENTS_DESIGN.md.
 *
 * Evaluates declarative detect-specs fetched from the backend. v1 scope is
 * intentionally small: only "npc_kill" specs whose conditions are visible in a
 * single frame (equipment state + inventory keywords). Session-window specs
 * (gp/hour, quest marathons) and minigame specs are server/telemetry work and
 * are IGNORED here - the tracker skips any condition key it doesn't support,
 * and skips the whole spec if any condition is unsupported (never false-claim).
 *
 * Soft-trust v1: claims are client-attested, like every community tracker.
 */

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public class AchievementTracker
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	// "Your TzTok-Jad kill count is: 1." / "Your Kalphite Queen kill count is: 42."
	private static final Pattern KILL_MSG = Pattern.compile("Your (.+?) (?:success count|kill count) is: ?([\\d,]+)");
	private static final Set<String> SUPPORTED_CONDITIONS = new HashSet<>(List.of(
		"equipment_empty", "equipment_all_match", "equipment_lacks", "inventory_lacks"));

	private final Client client;
	private final ItemManager itemManager;
	private final OkHttpClient http;
	private final Gson gson;
	private final String apiUrl;
	private final String linkKey;
	private final java.util.function.BooleanSupplier nameOnBoards;

	private final List<JsonObject> killSpecs = new ArrayList<>();
	// touched from the client thread and OkHttp callback threads
	private final Set<String> claimedThisSession = java.util.concurrent.ConcurrentHashMap.newKeySet();

	public AchievementTracker(Client client, ItemManager itemManager, OkHttpClient http,
		Gson gson, String apiUrl, String linkKey, java.util.function.BooleanSupplier nameOnBoards)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.http = http;
		this.gson = gson;
		this.apiUrl = apiUrl;
		this.linkKey = linkKey == null || linkKey.isEmpty() ? "qa" : linkKey;
		this.nameOnBoards = nameOnBoards;
	}

	/** Fetch detect specs once at startup; keep only what v1 can evaluate honestly. */
	public void loadSpecs()
	{
		Request req = new Request.Builder().url(apiUrl + "/achievements/specs").get().build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException e) { /* feed still works without */ }

			@Override public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null) return;
					JsonObject root = new JsonParser().parse(r.body().string()).getAsJsonObject();
					JsonArray arr = root.getAsJsonArray("achievements");
					synchronized (killSpecs)
					{
						killSpecs.clear();
						for (JsonElement el : arr)
						{
							JsonObject a = el.getAsJsonObject();
							JsonObject detect = a.getAsJsonObject("detect");
							if (detect == null || !"npc_kill".equals(str(detect, "event"))) continue;
							JsonObject cond = detect.getAsJsonObject("conditions");
							if (cond == null || !supported(cond)) continue;
							killSpecs.add(a);
						}
					}
				}
			}
		});
	}

	/** Call from the plugin's onChatMessage with GAMEMESSAGE text (colour tags stripped). */
	public void onGameMessage(String message)
	{
		Matcher m = KILL_MSG.matcher(message);
		if (!m.find()) return;
		String npc = m.group(1).trim();
		List<JsonObject> toEval;
		synchronized (killSpecs) { toEval = new ArrayList<>(killSpecs); }
		for (JsonObject a : toEval)
		{
			String id = str(a, "id");
			if (id == null || claimedThisSession.contains(id)) continue;
			JsonObject detect = a.getAsJsonObject("detect");
			if (!npc.equalsIgnoreCase(str(detect, "npc"))) continue;
			if (conditionsHold(detect.getAsJsonObject("conditions")))
			{
				claimedThisSession.add(id);
				claim(id);
			}
		}
	}

	private boolean supported(JsonObject cond)
	{
		for (String k : cond.keySet())
		{
			if (!SUPPORTED_CONDITIONS.contains(k)) return false;
		}
		return true;
	}

	private boolean conditionsHold(JsonObject cond)
	{
		if (cond == null) return false;
		if (cond.has("equipment_empty") && !equipmentEmpty(cond.getAsJsonArray("equipment_empty"))) return false;
		if (cond.has("equipment_all_match") && !equipmentAllMatch(cond.get("equipment_all_match").getAsString())) return false;
		if (cond.has("equipment_lacks") && containsKeyword(equippedNames(), cond.getAsJsonArray("equipment_lacks"))) return false;
		if (cond.has("inventory_lacks") && containsKeyword(inventoryNames(), cond.getAsJsonArray("inventory_lacks"))) return false;
		return true;
	}

	private boolean equipmentEmpty(JsonArray slots)
	{
		ItemContainer eq = client.getItemContainer(InventoryID.EQUIPMENT);
		if (eq == null) return true;
		for (JsonElement s : slots)
		{
			EquipmentInventorySlot slot = slotByName(s.getAsString());
			if (slot == null) return false;
			Item it = eq.getItem(slot.getSlotIdx());
			if (it != null && it.getId() > 0) return false;
		}
		return true;
	}

	private boolean equipmentAllMatch(String keyword)
	{
		List<String> names = equippedNames();
		if (names.isEmpty()) return false;
		String kw = keyword.toLowerCase();
		for (String n : names)
		{
			if (!n.toLowerCase().contains(kw)) return false;
		}
		return true;
	}

	private boolean containsKeyword(List<String> names, JsonArray keywords)
	{
		for (String n : names)
		{
			String low = n.toLowerCase();
			for (JsonElement k : keywords)
			{
				if (low.contains(k.getAsString().toLowerCase())) return true;
			}
		}
		return false;
	}

	private List<String> equippedNames() { return containerNames(InventoryID.EQUIPMENT); }
	private List<String> inventoryNames() { return containerNames(InventoryID.INVENTORY); }

	private List<String> containerNames(InventoryID cid)
	{
		List<String> out = new ArrayList<>();
		ItemContainer c = client.getItemContainer(cid);
		if (c == null) return out;
		for (Item it : c.getItems())
		{
			if (it == null || it.getId() <= 0) continue;
			out.add(itemManager.getItemComposition(it.getId()).getName());
		}
		return out;
	}

	private static EquipmentInventorySlot slotByName(String name)
	{
		switch (name.toLowerCase())
		{
			case "weapon": return EquipmentInventorySlot.WEAPON;
			case "shield": return EquipmentInventorySlot.SHIELD;
			case "body": return EquipmentInventorySlot.BODY;
			case "legs": return EquipmentInventorySlot.LEGS;
			case "head": return EquipmentInventorySlot.HEAD;
			case "cape": return EquipmentInventorySlot.CAPE;
			case "gloves": return EquipmentInventorySlot.GLOVES;
			case "boots": return EquipmentInventorySlot.BOOTS;
			case "amulet": return EquipmentInventorySlot.AMULET;
			case "ring": return EquipmentInventorySlot.RING;
			case "ammo": return EquipmentInventorySlot.AMMO;
			default: return null;
		}
	}

	private void claim(String achievementId)
	{
		Map<String, Object> snap = new HashMap<>();
		String player = client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null
			? client.getLocalPlayer().getName() : "";
		// display name goes to the public board only if the user opted in
		snap.put("player", nameOnBoards.getAsBoolean() ? player : "");
		snap.put("link_key", linkKey);
		snap.put("skills", new HashMap<>());
		String evidence = sha256(player + "|" + achievementId + "|" + System.currentTimeMillis());
		Request req = new Request.Builder()
			.url(apiUrl + "/achievements/claim?achievement_id=" + achievementId + "&evidence=" + evidence)
			.post(RequestBody.create(JSON, gson.toJson(snap)))
			.build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException e) { claimedThisSession.remove(achievementId); }
			@Override public void onResponse(Call call, Response response) { response.close(); }
		});
	}

	private static String sha256(String s)
	{
		try
		{
			MessageDigest md = MessageDigest.getInstance("SHA-256");
			StringBuilder sb = new StringBuilder();
			for (byte b : md.digest(s.getBytes(StandardCharsets.UTF_8)))
			{
				sb.append(String.format("%02x", b));
			}
			return sb.substring(0, 32);
		}
		catch (Exception e) { return "na"; }
	}

	private static String str(JsonObject o, String k)
	{
		return o != null && o.has(k) && !o.get(k).isJsonNull() ? o.get(k).getAsString() : null;
	}
}

