@Slf4j
@PluginDescriptor(
	name = "Genie",
	description = "Personalized money makers and unlock ladders for your account",
	tags = {"money", "gp", "efficiency", "planner"}
)
public class AccountCopilotPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private AccountCopilotConfig config;
	@Inject private ConfigManager configManager;
	@Inject private OkHttpClient httpClient;
	@Inject private ItemManager itemManager;
	@Inject private Gson gson;

	private CopilotPanel panel;
	private final Map<Integer, Integer> bankItems = new HashMap<>();
	private Map<String, Object> lastSnapshot;
	private long bankSyncedAt = 0;

	// ---- telemetry collector (frozen schema v1; see data-contract.md) ----
	private String sessionId = "";
	private final Map<String, Integer> xpCurrent = new ConcurrentHashMap<>();     // skill -> total xp
	private final Map<String, Integer> xpAtWindowStart = new HashMap<>();          // skill -> xp at window start
	private final Map<Integer, Integer> lootWindow = new ConcurrentHashMap<>();    // itemId -> qty gained this window
	private final Map<Integer, Integer> gatherWindow = new ConcurrentHashMap<>();  // itemId -> qty gathered into inventory this window (fallback)
	private final Map<String, Integer> gatherNames = new ConcurrentHashMap<>();    // item name -> count from GATHER CHAT (destination-independent: counts log-basket logs too)
	private long lastBankMs = 0;   // last time the bank container changed (banking guard)
	private final Map<Integer, Integer> lastInv = new HashMap<>();                 // last inventory counts, for diffing gains
	private int lastNpcId = -1;
	private String lastNpcName = "";
	private int lastAnimation = -1;
	private int lastRegion = -1;
	private long lastFlushMs = 0;
	private static final long TELEM_WINDOW_MS = 60_000;
	private int killCount = 0;           // NPC kills this window
	private long damageWindow = 0;       // damage the local player dealt this window
	private NavigationButton navButton;

	private AchievementTracker achievements;

	@Override
	protected void startUp()
	{
		panel = new CopilotPanel(this, itemManager);
		achievements = new AchievementTracker(client, itemManager, httpClient, gson,
			config.apiUrl(), config.linkKey(), () -> config.nameOnBoards());
		achievements.loadSpecs();
		showDataNoticeOnce();
		navButton = NavigationButton.builder()
			.tooltip("Genie")
			.icon(ImageUtil.loadImageResource(getClass(), "/icon.png"))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		SwingUtilities.invokeLater(() -> panel.setSynced(false, null));
		if (client.getGameState() == GameState.LOGGED_IN) requestPlan();
	}

	private long lastSyncMs = 0;

	@Override
	protected void shutDown() { clientToolbar.removeNavigation(navButton); }

	/** Plugin Hub norm: tell the user exactly what leaves their client, once. */
	private void showDataNoticeOnce()
	{
		String key = "dataNoticeShown";
		if (Boolean.TRUE.toString().equals(configManager.getConfiguration("accountcopilot", key)))
		{
			return;
