	// Gather messages fire when you obtain the resource, BEFORE it routes to inventory or
	// a log basket - so this counts basket logs that inventory diffing never sees.
	private static final java.util.regex.Pattern[] GATHER = {
		java.util.regex.Pattern.compile("You get some ([a-z][a-z '-]+?)\\."),          // woodcutting logs / bark
		java.util.regex.Pattern.compile("You (?:manage to )?mine some ([a-z][a-z '-]+?)\\."), // mining ore
		java.util.regex.Pattern.compile("You catch (?:an?|some) ([a-z][a-z '-]+?)[.!]"),  // fishing
		java.util.regex.Pattern.compile("You (?:pick|harvest|gather) (?:some|an?) ([a-z][a-z '-]+?)\\.") // farming / misc
	};
	private void parseGather(String msg)
	{
		String low = msg.toLowerCase();
		for (java.util.regex.Pattern p : GATHER)
		{
			java.util.regex.Matcher mt = p.matcher(low);
			if (mt.find())
			{
				String name = mt.group(1).trim();
				if (name.length() >= 3) gatherNames.merge(name, 1, Integer::sum);
				return;
			}
		}
		if (low.contains("bird's nest")) gatherNames.merge("bird nest", 1, Integer::sum);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() == InventoryID.BANK.getId())
		{
			bankItems.clear();
			for (Item it : e.getItemContainer().getItems())
			{
				// quantity check filters bank placeholders (qty 0 = you don't actually own it)
				if (it.getId() > 0 && it.getQuantity() > 0) bankItems.put(it.getId(), it.getQuantity());
			}
			bankSyncedAt = System.currentTimeMillis() / 1000;
			lastBankMs = System.currentTimeMillis();
		}
		else if (e.getContainerId() == InventoryID.INVENTORY.getId())
		{
			// diff inventory to record what was GATHERED (logs, ore, fish, herbs...) this window.
			// If the bank changed in the last ~1.2s you're banking: withdrawals aren't gathering,
			// so re-baseline and skip. (Avoids the deprecated Widget API entirely.)
			if (System.currentTimeMillis() - lastBankMs < 1200)
			{
				snapshotInv(e.getItemContainer());
				return;
			}
			Map<Integer, Integer> cur = new HashMap<>();
			for (Item it : e.getItemContainer().getItems())
			{
				if (it.getId() > 0) cur.merge(it.getId(), it.getQuantity(), Integer::sum);
			}
			if (!lastInv.isEmpty())
			{
				for (Map.Entry<Integer, Integer> en : cur.entrySet())
				{
					int delta = en.getValue() - lastInv.getOrDefault(en.getKey(), 0);
					if (delta > 0 && delta < 10000) gatherWindow.merge(en.getKey(), delta, Integer::sum);
				}
			}
			lastInv.clear();
			lastInv.putAll(cur);
		}
	}

	private void snapshotInv(ItemContainer inv)
	{
		lastInv.clear();
		if (inv == null) return;
		for (Item it : inv.getItems()) if (it.getId() > 0) lastInv.merge(it.getId(), it.getQuantity(), Integer::sum);
	}

