	private boolean friendsSynced = false;

	/** Hash the friends list and sync it, once per login, if the user allows it.
	 *  Raw names never leave the client: sha256(normalized name), 32 hex chars. */
	private void syncFriends()
	{
		if (friendsSynced || !config.syncFriends()) return;
		net.runelite.api.FriendContainer fc = client.getFriendContainer();
		if (fc == null) return;
		StringBuilder sb = new StringBuilder();
		for (net.runelite.api.Friend f : fc.getMembers())
		{
			if (f == null || f.getName() == null) continue;
			String norm = f.getName().replace(' ', ' ').replace('_', ' ').trim().toLowerCase();
			String h = sha256_32(norm);
			if (h != null) { if (sb.length() > 0) sb.append(','); sb.append(h); }
		}
		friendsSynced = true;
		if (sb.length() == 0) return;
		Map<String, Object> snap = new HashMap<>();
		snap.put("player", "");
		snap.put("link_key", config.linkKey().isEmpty() ? "qa" : config.linkKey());
		snap.put("skills", new HashMap<>());
		Request req = new Request.Builder()
			.url(config.apiUrl() + "/friends/sync?hashes=" + sb)
			.post(RequestBody.create(MediaType.parse("application/json"), gson.toJson(snap)))
			.build();
		httpClient.newCall(req).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException ex) { friendsSynced = false; }
			@Override public void onResponse(Call call, Response response) { response.close(); }
		});
	}

	private static String sha256_32(String s)
	{
		try
		{
			java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
			StringBuilder sb = new StringBuilder();
			for (byte b : md.digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8)))
			{
				sb.append(String.format("%02x", b));
			}
			return sb.substring(0, 32);
		}
		catch (Exception e) { return null; }
	}

