	private void postDrop(int itemId, int qty, long value, String npc)
	{
		String itemName;
		try { itemName = itemManager.getItemComposition(itemId).getName(); }
		catch (Exception ex) { return; }
		Map<String, Object> snap = new HashMap<>();
		Player me = client.getLocalPlayer();
		snap.put("player", me != null && me.getName() != null ? me.getName() : "");
		snap.put("link_key", config.linkKey().isEmpty() ? "qa" : config.linkKey());
		snap.put("skills", new HashMap<>());
		String url;
		try
		{
			url = config.apiUrl() + "/drops?item_name="
				+ java.net.URLEncoder.encode(itemName, java.nio.charset.StandardCharsets.UTF_8.name())
				+ "&value=" + value + "&qty=" + qty
				+ "&npc=" + java.net.URLEncoder.encode(npc, java.nio.charset.StandardCharsets.UTF_8.name());
		}
		catch (Exception ex) { return; }
		Request req = new Request.Builder()
			.url(url)
			.post(RequestBody.create(MediaType.parse("application/json"), gson.toJson(snap)))
			.build();
		httpClient.newCall(req).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException ex) { }
			@Override public void onResponse(Call call, Response response) { response.close(); }
		});
