	@Subscribe
	public void onGameTick(GameTick t)
	{
		if (client.getGameState() != GameState.LOGGED_IN) return;
		Player me = client.getLocalPlayer();
		if (me == null) return;
		if (sessionId.isEmpty()) sessionId = UUID.randomUUID().toString();

		Actor target = me.getInteracting();
		if (target instanceof NPC)
		{
			NPC n = (NPC) target;
			lastNpcId = n.getId();
			lastNpcName = n.getName() != null ? n.getName() : "";
		}
		int anim = me.getAnimation();
		if (anim != -1) lastAnimation = anim;
		if (me.getWorldLocation() != null) lastRegion = me.getWorldLocation().getRegionID();

		long now = System.currentTimeMillis();
		if (lastFlushMs == 0) lastFlushMs = now;
		if (now - lastFlushMs >= TELEM_WINDOW_MS) flushTelemetry(now);
		if (!linkKeyMissing() && now - lastSyncMs >= 60_000) { lastSyncMs = now; requestPlan(); }
		syncFriends();
	}

	/** Build one telemetry sample for the last window and POST it (if sharing is enabled). */
	private void flushTelemetry(long now)
	{
		long durMs = now - lastFlushMs;
		lastFlushMs = now;
		Player me = client.getLocalPlayer();
		if (!config.shareTelemetry() || me == null || me.getName() == null) { resetWindow(); return; }

		Map<String, Integer> gained = new HashMap<>();
		Map<String, Integer> totals = new HashMap<>();
		for (Map.Entry<String, Integer> en : xpCurrent.entrySet())
		{
			totals.put(en.getKey(), en.getValue());
			int base = xpAtWindowStart.getOrDefault(en.getKey(), en.getValue());
			int d = en.getValue() - base;
			if (d > 0) gained.put(en.getKey(), d);
		}
		if (gained.isEmpty() && lootWindow.isEmpty() && gatherWindow.isEmpty() && gatherNames.isEmpty()) { resetWindow(); return; } // idle window -> skip

		Map<String, Object> sample = new HashMap<>();
		sample.put("schema", 1);
		sample.put("player_hash", sha256(me.getName()));
		sample.put("session_id", sessionId);
		sample.put("ts", now / 1000);
		sample.put("duration_s", (int) (durMs / 1000));
		boolean members = client.getWorldType() != null && client.getWorldType().contains(WorldType.MEMBERS);
		sample.put("members", members);
		try { sample.put("account_type", client.getVarbitValue(Varbits.ACCOUNT_TYPE)); } catch (Exception ex) { sample.put("account_type", 0); }
		Map<String, Integer> levels = new HashMap<>();
		for (Skill sk : Skill.values()) levels.put(prettySkill(sk.getName()), client.getRealSkillLevel(sk));
		sample.put("skills", levels);
		sample.put("xp_total", totals);
		sample.put("xp_gained", gained);
		sample.put("interacting_npc_id", lastNpcId);
		sample.put("interacting_npc_name", lastNpcName);
		sample.put("animation", lastAnimation);
		sample.put("region_id", lastRegion);
		List<Integer> eq = new ArrayList<>();
		ItemContainer ec = client.getItemContainer(InventoryID.EQUIPMENT);
		if (ec != null) for (Item it : ec.getItems()) if (it.getId() > 0) eq.add(it.getId());
		sample.put("equipped", eq);
		Map<String, Integer> loot = new HashMap<>();
		for (Map.Entry<Integer, Integer> en : lootWindow.entrySet()) loot.put(String.valueOf(en.getKey()), en.getValue());
		sample.put("loot", loot);
		Map<String, Integer> gathered = new HashMap<>();
		for (Map.Entry<Integer, Integer> en : gatherWindow.entrySet()) gathered.put(String.valueOf(en.getKey()), en.getValue());
		sample.put("gathered", gathered);
		sample.put("gathered_names", new HashMap<>(gatherNames));

		// ---- net-worth signals (valued with RuneLite's own GE prices) ----
		long invValue = valueContainer(client.getItemContainer(InventoryID.INVENTORY));
		long eqValue = valueContainer(client.getItemContainer(InventoryID.EQUIPMENT));
		long bankValue = 0;
		for (Map.Entry<Integer, Integer> en : bankItems.entrySet())
		{
			bankValue += priceOf(en.getKey()) * (long) en.getValue();
		}
		long geValue = 0;
		List<Map<String, Object>> geOffers = new ArrayList<>();
		try
		{
			GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
			if (offers != null)
			{
				for (int i = 0; i < offers.length; i++)
				{
					GrandExchangeOffer o = offers[i];
					if (o == null || o.getItemId() <= 0) continue;
					boolean buy = o.getState() != null && o.getState().name().startsWith("BUY");
					int remaining = o.getTotalQuantity() - o.getQuantitySold();
					geValue += (long) o.getPrice() * Math.max(0, remaining);   // gp still committed/expected
					Map<String, Object> off = new HashMap<>();
					off.put("item_id", o.getItemId());
					off.put("price", o.getPrice());
					off.put("total_qty", o.getTotalQuantity());
					off.put("sold_qty", o.getQuantitySold());
					off.put("buy", buy);
					off.put("state", o.getState() != null ? o.getState().name() : "");
					geOffers.add(off);
				}
			}
		}
		catch (Exception ignored) {}
		sample.put("bank_value", bankValue);
		sample.put("inventory_value", invValue);
		sample.put("equipment_value", eqValue);
		sample.put("ge_value", geValue);
		sample.put("total_wealth", bankValue + invValue + eqValue + geValue);
		sample.put("ge_offers", geOffers);
		// inventory contents (for processing/gathering gp)
		Map<String, Integer> invItems = new HashMap<>();
		ItemContainer invC = client.getItemContainer(InventoryID.INVENTORY);
		if (invC != null) for (Item it : invC.getItems()) if (it.getId() > 0) invItems.merge(String.valueOf(it.getId()), it.getQuantity(), Integer::sum);
		sample.put("inventory", invItems);
		// combat measurement
		sample.put("kill_count", killCount);
		sample.put("damage_dealt", damageWindow);

		postTelemetry(sample);
		resetWindow();
	}

	private void resetWindow()
	{
		xpAtWindowStart.clear();
		xpAtWindowStart.putAll(xpCurrent);
		lootWindow.clear();
		gatherWindow.clear();
		gatherNames.clear();
		killCount = 0;
		damageWindow = 0;
	}

	private void postTelemetry(Map<String, Object> sample)
	{
		Map<String, Object> payload = new HashMap<>();
		List<Map<String, Object>> batch = new ArrayList<>();
		batch.add(sample);
		payload.put("samples", batch);
		payload.put("client_version", "genie-plugin/0.1.0 schema1");
		Request req = new Request.Builder()
			.url(config.apiUrl() + "/telemetry")
			.post(RequestBody.create(MediaType.parse("application/json"), gson.toJson(payload)))
			.build();
		httpClient.newCall(req).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException e) { log.debug("telemetry post failed", e); }
			@Override public void onResponse(Call call, Response response) throws IOException { response.close(); }
		});
	}

	private long priceOf(int itemId)
	{
		if (itemId == 995) return 1;                 // coins
		try { return Math.max(0, itemManager.getItemPrice(itemId)); } catch (Exception e) { return 0; }
	}

	private long valueContainer(ItemContainer c)
	{
		long v = 0;
		if (c != null) for (Item it : c.getItems()) if (it.getId() > 0) v += priceOf(it.getId()) * (long) it.getQuantity();
		return v;
	}

	private String sha256(String name)
	{
		try
		{
			MessageDigest md = MessageDigest.getInstance("SHA-256");
			byte[] h = md.digest(name.toLowerCase().getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder();
			for (byte b : h) sb.append(String.format("%02x", b));
			return sb.toString();
		}
		catch (Exception e) { return ""; }
	}

